export default async function plan(
  { body, assessment, stage, destination, spreadsheetId, range, acknowledge, resolution },
  ctx,
) {
  if (!body?.submissionId || !body?.name || !body?.email || !body?.text || !body?.filename)
    throw Error("Missing application fields");
  if (stage === "sheet" && (!spreadsheetId || spreadsheetId.includes("YOUR_") || !range))
    throw Error("Configure spreadsheet");
  if (stage === "hr" && (!destination || destination.includes("YOUR_")))
    throw Error("Configure HR recipient");
  const key = "application:" + body.submissionId + ":" + stage,
    old = await ctx.state.get(key),
    to = stage === "hr" ? destination : body.email;
  const text =
    stage === "hr"
      ? `New CV awaiting review\nName: ${body.name}\nEmail: ${body.email}\nLinkedIn: ${body.linkedin}\nExpectation: ${body.expectation}\nAssessment: ${assessment}`
      : `Dear ${body.name},\n\nThank you for submitting your CV. We have received it and will review it shortly.`;
  const result = {
    key,
    write: false,
    to,
    text,
    spreadsheetId,
    range,
    values: [[body.filename, body.name, body.email, body.expectation, body.linkedin, assessment]],
  };
  if (old?.status === "done") return result;
  if (old?.status === "pending") {
    if (acknowledge !== key || !["confirmed", "absent"].includes(resolution))
      throw Error("Inspect pending " + key);
    if (resolution === "confirmed") {
      await ctx.state.set(key, { status: "done" });
      return result;
    }
  }
  await ctx.state.set(key, { status: "pending" });
  return { ...result, write: true };
}

